use crate::aap::caps::{http_client, state_read};

struct Node;

/// Keys tried, in order, in the 'subscriptions' store.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(text: &str) -> Option<Vec<String>> {
    let mut chars = text.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut s = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => s.push('"'),
                            '\\' => s.push('\\'),
                            '/' => s.push('/'),
                            'b' => s.push('\u{8}'),
                            'f' => s.push('\u{c}'),
                            'n' => s.push('\n'),
                            'r' => s.push('\r'),
                            't' => s.push('\t'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                            _ => return None,
                        },
                        c => s.push(c),
                    }
                }
                out.push(s);
            }
            _ => return None,
        }
    }
    Some(out)
}

fn parse_urls(raw: &str) -> Vec<String> {
    let candidates: Vec<String> = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .split(|c: char| c == '\n' || c == ',' || c == '\r')
            .map(|s| s.to_string())
            .collect(),
    };
    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (approved grant extension). The result is not used,
        // so the node's output is unchanged; transport failures are tolerated.
        let enrich_url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }

        // `ensures present(urls)`: never emit an output that violates it.
        panic!("LoadSubscriptions: no subscription URLs found in 'subscriptions' store");
    }
}

export!(Node);
